mapper.select:
SELECT p.id FROM t_profiles p WHERE p.my_invite_code=#{code}
 AND (EXISTS(SELECT 1 FROM t_profiles me WHERE me.id=#{actor} AND me.is_admin=1)
      OR p.invited_by=#{actor}) LIMIT 1

SELECT p.my_invite_code FROM t_profiles p WHERE p.id=#{operator}
  AND (p.id=#{actor}
    OR EXISTS(SELECT 1 FROM t_profiles me WHERE me.id=#{actor} AND me.is_admin=1)
    OR EXISTS(SELECT 1 FROM t_join_applications ja WHERE ja.operator_id=#{operator}
            AND ja.target_user_id=#{actor} AND ja.status='pending')) LIMIT 1
